import re


def eval_expression(expr):
    # 1. 空白文字を削除
    expr = expr.replace(" ", "")

    # 2. 字句解析（トークナイザー）: 数値、演算子、括弧に分解する
    # 負の数を正しく認識するため、マイナス記号の扱いを調整します
    # ここでは正規表現で数値（小数含む）、演算子、括弧を抽出します
    token_pattern = re.compile(r"(?:\d+\.\d+|\d+|\+|\-|\*|/|\(|\))")
    tokens = token_pattern.findall(expr)

    # トークンが正しく分割できているか、余計な文字がないかチェック
    if "".join(tokens) != expr:
        raise ValueError(f"無効な文字が含まれています: {expr}")

    if not tokens:
        raise ValueError("空の式です。")

    class Parser:

        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(tokens):
                return self.tokens[self.pos]
            return None

        def consume(self):
            token = self.peek()
            self.pos += 1
            return token

        # 式 = 項 { (+ | -) 項 }
        def parse_expression(self):
            node = self.parse_term()
            while self.peek() in ("+", "-"):
                op = self.consume()
                right = self.parse_term()
                if op == "+":
                    node = node + right
                else:
                    node = node - right
            return node

        # 項 = 因子 { (* | /) 因子 }
        def parse_term(self):
            node = self.parse_factor()
            while self.peek() in ("*", "/"):
                op = self.consume()
                right = self.parse_factor()
                if op == "*":
                    node = node * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("ゼロによる除算です。")
                    node = node / right  # Python 3では浮動小数点数除算
            return node

        # 因子 = 数値 | '(' 式 ')' | UnaryPlus | UnaryMinus (負の数対応)
        def parse_factor(self):
            token = self.peek()

            # 単項プラス・マイナス（負の数対応）
            if token == "+":
                self.consume()
                return self.parse_factor()
            if token == "-":
                self.consume()
                return -self.parse_factor()

            # 括弧
            if token == "(":
                self.consume()
                node = self.parse_expression()
                if self.consume() != ")":
                # if self.consume() != ")":  # 修正: 括弧の対応チェック
                    raise ValueError("閉じ括弧がありません。")
                return node

            # 数値
            if token is not None:
                self.consume()
                try:
                    # 整数または浮動小数点数に変換
                    return float(token) if "." in token else int(token)
                except ValueError:
                    raise ValueError(f"無効な数値です: {token}")

            raise ValueError("予期せぬ式の終わりです。")

    parser = Parser(tokens)
    result = parser.parse_expression()

    # パースしきれずにトークンが残っている場合
    if parser.peek() is not None:
        raise ValueError(f"構文エラーです: {parser.peek()}")

    return result


# --- テスト・使用例 ---
if __name__ == "__main__":
    print(eval_expression("3 + 4 * (2 - 1)"))  # 出力: 7
    print(eval_expression("-5 + 3"))  # 出力: -2 (負の数)
    print(eval_expression("10 / (2 + 3)"))  # 出力: 2.0
    print(eval_expression("  -2 * ( -3 + 5 ) "))  # 出力: -4

    try:
        eval_expression("5 / 0")
    except ZeroDivisionError as e:
        print(e)  # 出力: ゼロによる除算です。
